// Python-string semantics helpers (black-box reimplementation).

// Compare two strings the way Python's str.__lt__ does: lexicographically
// by Unicode code point (not UTF-16 code unit, which differs outside the BMP).
export function pyStrCompare(a, b) {
  const ia = Array.from(a);
  const ib = Array.from(b);
  const n = Math.min(ia.length, ib.length);
  for (let i = 0; i < n; i++) {
    const ca = ia[i].codePointAt(0);
    const cb = ib[i].codePointAt(0);
    if (ca !== cb) return ca < cb ? -1 : 1;
  }
  if (ia.length === ib.length) return 0;
  return ia.length < ib.length ? -1 : 1;
}

// Equivalent of Python's sorted() on a list of strings (returns a new list).
export function pySorted(strings) {
  return [...strings].sort(pyStrCompare);
}

// Equivalent of Python's str.encode('utf-8'): returns an array of byte values.
export function utf8Bytes(str) {
  return Array.from(new TextEncoder().encode(str));
}

