// Canonical JSON encoder, reimplemented from the observed behavior of
// canonicaljson.encode_canonical_json: compact separators, no ASCII
// escaping of non-ASCII characters (they stay as raw UTF-8 once encoded),
// control characters escaped like Python's json.dumps.

import { pyStrCompare } from './pyString.mjs';

// Escape a string exactly as Python's json.dumps(..., ensure_ascii=False):
// \" and \\, short escapes for \b \f \n \r \t, \u00xx (lowercase hex) for
// other characters below 0x20, everything else (including >= 0x7f) raw.
export function escapeJsonString(str) {
  let out = '"';
  for (const ch of str) {
    const cp = ch.codePointAt(0);
    if (ch === '"') {
      out += '\\"';
    } else if (ch === '\\') {
      out += '\\\\';
    } else if (cp === 0x08) {
      out += '\\b';
    } else if (cp === 0x09) {
      out += '\\t';
    } else if (cp === 0x0a) {
      out += '\\n';
    } else if (cp === 0x0c) {
      out += '\\f';
    } else if (cp === 0x0d) {
      out += '\\r';
    } else if (cp < 0x20) {
      out += '\\u' + cp.toString(16).padStart(4, '0');
    } else {
      out += ch;
    }
  }
  return out + '"';
}

// Encode a value as canonical JSON text (compact separators, sorted object
// keys). Supports the JSON data model: null, booleans, numbers, strings,
// arrays, and plain objects.
export function encodeCanonicalJson(value) {
  if (value === null || value === undefined) return 'null';
  if (value === true) return 'true';
  if (value === false) return 'false';
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new Error('Out of range float values are not JSON compliant');
    }
    return String(value);
  }
  if (typeof value === 'string') return escapeJsonString(value);
  if (Array.isArray(value)) {
    return '[' + value.map(encodeCanonicalJson).join(',') + ']';
  }
  if (typeof value === 'object') {
    const keys = Object.keys(value).sort(pyStrCompare);
    const parts = keys.map(
      (k) => escapeJsonString(k) + ':' + encodeCanonicalJson(value[k])
    );
    return '{' + parts.join(',') + '}';
  }
  throw new Error(`Object of type ${typeof value} is not JSON serializable`);
}

