// Reimplementation of Python's repr() for bytes objects, matching CPython's
// bytes_repr: single quotes by default (double quotes only if the data
// contains a single quote but no double quote), backslash and quote escaped,
// \t \n \r shortcuts, printable ASCII raw, all other bytes as \xHH.

function hexByte(b) {
  return '\\x' + b.toString(16).padStart(2, '0');
}

// bytes: array of integers 0..255. Returns the exact text Python's
// print(repr(b'...')) would show, including the leading b and quotes.
export function pyBytesRepr(bytes) {
  let quote = "'";
  if (bytes.includes(0x27) && !bytes.includes(0x22)) {
    quote = '"';
  }
  const q = quote.charCodeAt(0);
  let out = 'b' + quote;
  for (const b of bytes) {
    if (b === q || b === 0x5c) {
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b >= 0x20 && b < 0x7f) {
      out += String.fromCharCode(b);
    } else {
      out += hexByte(b);
    }
  }
  return out + quote;
}

