// Minimal reimplementation of Python's argparse behavior for this program:
// two required string options (--a, --b) plus -h/--help. Reproduces
// argparse's usage/error text, exit codes (2 on error, 0 on help),
// --opt=value form, unambiguous prefix abbreviation, and the rule that an
// option-like token is not consumed as a value (negative numbers are).

import { basename } from 'node:path';

const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

const OPTIONS = [
  { names: ['-h', '--help'], dest: 'help', takesValue: false },
  { names: ['--a'], dest: 'a', metavar: 'A', takesValue: true },
  { names: ['--b'], dest: 'b', metavar: 'B', takesValue: true },
];

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B`;
}

function printHelp(prog) {
  console.log(
    usageLine(prog) +
      '\n\noptions:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n' +
      '  --b B'
  );
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

// True when argparse would treat the token as an option string rather than
// a value (a lone '-' is a value; negative numbers are values).
function looksLikeOption(token) {
  if (!token.startsWith('-') || token === '-') return false;
  if (NEGATIVE_NUMBER.test(token)) return false;
  return true;
}

export function parseArgs(argv, progPath) {
  const prog = basename(progPath);
  const result = {};
  const extras = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];

    if (token === '--') {
      // Everything after '--' is positional; this program has none.
      extras.push(...argv.slice(i + 1));
      break;
    }

    if (looksLikeOption(token)) {
      // Split --opt=value form (short options don't take '=' here).
      let name = token;
      let inlineValue = null;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      // Exact match first, then unambiguous prefix abbreviation.
      let option = OPTIONS.find((o) => o.names.includes(name));
      if (!option && name.startsWith('--')) {
        const matches = OPTIONS.filter((o) =>
          o.names.some((n) => n.startsWith('--') && n.startsWith(name))
        );
        if (matches.length === 1) {
          option = matches[0];
        } else if (matches.length > 1) {
          const opts = matches.map((m) => m.names[m.names.length - 1]);
          fail(prog, `ambiguous option: ${name} could match ${opts.join(', ')}`);
        }
      }

      if (!option) {
        extras.push(token);
        continue;
      }

      if (!option.takesValue) {
        if (inlineValue !== null) {
          fail(prog, `argument ${option.names[0]}: ignored explicit argument '${inlineValue}'`);
        }
        printHelp(prog);
        process.exit(0);
      }

      if (inlineValue !== null) {
        result[option.dest] = inlineValue;
      } else {
        const next = argv[i + 1];
        if (next === undefined || looksLikeOption(next)) {
          fail(prog, `argument ${option.names[0]}: expected one argument`);
        }
        result[option.dest] = next;
        i++;
      }
    } else {
      // Positional token; this program declares none.
      extras.push(token);
    }
  }

  // argparse reports missing required arguments before unrecognized ones.
  const missing = OPTIONS.filter(
    (o) => o.takesValue && result[o.dest] === undefined
  ).map((o) => o.names[0]);
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return result;
}

