#!/usr/bin/env node
// Node.js (ESM) port of test7.py: encodes [a, b] and sorted([a, b]) as
// canonical JSON and prints them as Python would print the resulting bytes.

import { parseArgs } from './lib/argparse.mjs';
import { encodeCanonicalJson } from './lib/jsonEncoder.mjs';
import { pyBytesRepr } from './lib/pyBytesRepr.mjs';
import { pySorted, utf8Bytes } from './lib/pyString.mjs';

function encodeCanonicalJsonBytes(value) {
  return utf8Bytes(encodeCanonicalJson(value));
}

function main() {
  const args = parseArgs(process.argv.slice(2), process.argv[1]);

  const data = [args.a, args.b];
  const result1 = encodeCanonicalJsonBytes(data);
  const result2 = encodeCanonicalJsonBytes(pySorted(data));
  console.log(pyBytesRepr(result1));
  console.log(pyBytesRepr(result2));
}

main();

